<?php
namespace App\Http\Controllers\Api\Admin;use App\Http\Controllers\Controller;use App\Services\Notification\NotificationService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class NotificationController extends Controller{public function index(){return DB::table('user_notifications')->where('type','announcement')->select('title','message','action_url',DB::raw('COUNT(*) as recipients'),DB::raw('MAX(created_at) as sent_at'))->groupBy('title','message','action_url')->orderByDesc('sent_at')->paginate(20);}public function store(Request $r,NotificationService $notifications){$data=$r->validate(['title'=>'required|string|max:150','message'=>'required|string|max:2000','action_url'=>'nullable|string|max:500']);return response()->json(['recipients'=>$notifications->broadcast($data['title'],$data['message'],$data['action_url']??null)],201);}}
